ticipants''||(t->''participants'')) id order by id),\n  case when nullif(f.starts_at,'''') is not null and nullif(f.home_id,'''') is not null and nullif(f.away_id,'''') is not null and f.home_id<>f.away_id\n   then least(f.home_id,f.away_id)||''|''||greatest(f.home_id,f.away_id) end,b,t\n from descriptors d\n cross join lateral(select case when (t->>''hasStart'')::boolean then t->>''starts'' else b->>''starts'' end starts_at,\n  case when (t->>''hasHome'')::boolean then t->>''home'' else b->>''home'' end home_id,\n  case when (t->>''hasAway'')::boolean then t->>''away'' else b->>''away'' end away_id) f;\n$function$\n"},{"signature":"nothingsports_fixture_read_private.enforce_pending_integrity()","contract":{"acl":"{postgres=X/postgres}","cost":100,"owner":"postgres","config":["search_path=\"\""],"strict":false,"definer":true,"parallel":"u","volatile":"v","leakproof":false,"definition":"6e211988e06c52d9ddfb7eee5cc5b908"},"source":"CREATE OR REPLACE FUNCTION nothingsports_fixture_read_private.enforce_pending_integrity()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\nbegin\n if exists(select 1 from nothingsports_fixture_read_private.integrity_pending where source_id=new.source_id and batch_xid is not null)then raise exception using errcode=''23514'',message=''Unclosed canonical batch'';end if;\n if not exists(select 1 from nothingsports_fixture_read_private.integrity_pending where source_id=new.source_id) then return null;end if;\n if not nothingsports_fixture_read_private.source_index_complete(new.source_id) then\n  raise exception using errcode=''23514'',message=''Fixture index integrity is incomplete; canonical transaction refused'';\n end if;\n delete from nothingsports_fixture_read_private.integrity_pending where source_id=new.source_id;\n return null;\nend;\n$function$\n"},{"signature":"nothingsports_fixture_read_private.mark_integrity_pending()","contract":{"acl":"{postgres=X/postgres}","cost":100,"owner":"postgres","config":["search_path=\"\""],"strict":false,"definer":true,"parallel":"u","volatile":"v","leakproof":false,"definition":"7ea78bfefb71f46ede7d35d7d656e14e"},"source":"CREATE OR REPLACE FUNCTION nothingsports_fixture_read_private.mark_integrity_pending()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\nbegin\n if tg_op<>''INSERT'' then\n  insert into nothingsports_fixture_read_private.integrity_pending(source_id) values(old.source_id) on conflict do nothing;\n end if;\n if tg_op<>''DELETE'' then\n  insert into nothingsports_fixture_read_private.integrity_pending(source_id) values(new.source_id) on conflict do nothing;\n end if;\n return null;\nend;\n$function$\n"},{"signature":"nothingsports_fixture_read_private.publish_compact_complete(text,uuid,jsonb,jsonb,text,integer,jsonb)","contract":{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"owner":"postgres","config":["search_path=\"\""],"strict":false,"definer":true,"parallel":"u","volatile":"v","leakproof":false,"definition":"0a2535591819d5fc729b6214190f3484"},"source":"CREATE OR REPLACE FUNCTION nothingsports_fixture_read_private.publish_compact_complete(p_source_id text, p_token uuid, p_fixtures jsonb, p_scores jsonb, p_hash text, p_interval_ms integer, p_report jsonb DEFAULT NULL::jsonb)\n RETURNS bigint\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n current_row public.nothingsports_fixture_sources; revision bigint; published jsonb; changed_ids text[]; score_changed_ids text[]; sync_id text; pending_preexisted boolean;\n score_keys text[]:=array[''homeScore'',''awayScore'',''scoreDisplay'',''score'',''sets'',''games'',''innings'',''rubbers'',''canonicalResultScoreline''];\n controls text[]:=array[''observationSchema'',''scoreObserved'',''statusObserved''];\n incoming jsonb; prior jsonb; next_score jsonb; score_facts jsonb; prior_facts jsonb; base jsonb; bases jsonb; previous_scores jsonb;\n receipts jsonb; receipt jsonb; report jsonb; accepted jsonb[]:=''{}''::jsonb[]; receipt_updates jsonb[]:=''{}''::jsonb[];\n score_at timestamptz; status_at timestamptz; prior_score_at timestamptz; prior_status_at timestamptz;\n score_ok boolean; status_ok boolean; legacy boolean; fid text;\nbegin\n select * into current_row from public.nothingsports_fixture_sources where source_id=p_source_id for update;\n if p_token is null or current_row.source_id is null or current_row.lease_token is distinct from p_token or current_row.lease_until is null or current_row.lease_until<=clock_timestamp() then raise exception ''Lease expired''; end if;\n if p_scores is null or jsonb_typeof(p_scores)<>''array'' or jsonb_array_length(p_scores)>5000 or\n    p_fixtures is null or jsonb_typeof(p_fixtures)<>''array'' or jsonb_array_length(p_fixtures)>5000 then raise exception ''Invalid compact observation budget''; end if;\n if p_report is not null and jsonb_typeof(p_report)<>''object'' then raise exception ''Invalid report''; end if;\n if exists(select 1 from jsonb_array_elements(p_scores) s group by s->>''id'' having count(*)>1) then raise exception ''Ambiguous compact identity''; end if;\n receipts:=coalesce(current_row.discovery_report->''_fixtureObservations'',''{}''::jsonb);\n select jsonb_object_agg(coalesce(value->>''id'',value->>''eventId'',value->>''canonicalEventId''),value) into bases from jsonb_array_elements(p_fixtures);\n select coalesce(jsonb_object_agg(fixture_id,score),''{}''::jsonb) into previous_scores from public.nothingsports_live_scores where source_id=p_source_id;\n for incoming in select value from jsonb_array_elements(p_scores) loop\n  fid:=incoming->>''id'';\n  base:=bases->fid;\n  if fid is null or fid='''' or base is null then raise exception ''Unmatched compact identity''; end if;\n  prior:=previous_scores->fid;\n  prior:=coalesce(prior,''{}''::jsonb); next_score:=prior;\n  receipt:=coalesce(receipts->fid,''{}''::jsonb);\n  legacy:=incoming->>''observationSchema'' is distinct from ''fixture-observations.v1'';\n  score_at:=public.nothingsports_fixture_observation_time(case when legacy then coalesce(incoming->>''scoreCheckedAt'',base->>''scoreCheckedAt'',base->>''sourceCheckedAt'',base->>''canonicalSourceCheckedAt'') when incoming->>''scoreObserved''=''true'' then incoming->>''scoreCheckedAt'' end);\n  status_at:=public.nothingsports_fixture_observation_time(case when legacy then coalesce(incoming->>''statusCheckedAt'',base->>''statusCheckedAt'',base->>''sourceCheckedAt'',base->>''canonicalSourceCheckedAt'') when incoming->>''statusObserved''=''true'' then incoming->>''statusCheckedAt'' end);\n  prior_score_at:=public.nothingsports_fixture_observation_time(coalesce(receipt->>''s'',prior->>''scoreCheckedAt''));\n  prior_status_at:=public.nothingsports_fixture_observation_time(coalesce(receipt->>''t'',prior->>''statusCheckedAt''));\n  select coalesce(jsonb_object_agg(key,value),''{}''::jsonb) into score_facts from jsonb_each(incoming) where key=any(score_keys) and value<>''null''::jsonb and value<>''[]''::jsonb and value<>''{}''::jsonb and value<>''\"\"''::jsonb;\n  select coalesce(jsonb_object_agg(key,value),''{}''::jsonb) into prior_facts from jsonb_each(prior) where key=any(score_keys) and value<>''null''::jsonb and value<>''[]''::jsonb and value<>''{}''::jsonb and value<>''\"\"''::jsonb;\n  -- Unknown-clock data can initialise legacy rows, but cannot replace known facts.\n  -- Equal clocks verify the same facts; contradictory equal-clock facts are rejected.\n  score_ok:=score_facts<>''{}''::jsonb and (prior=''{}''::jsonb or\n    (score_at is not null and (prior_score_at is null or score_at>prior_score_at or score_at=prior_score_at and score_facts=prior_facts)) or\n    (legacy and score_at is null and prior_score_at is null));\n  status_ok:=nullif(incoming->>''status'','''') is not null and (prior=''{}''::jsonb or\n    (status_at is not null and (prior_status_at is null or status_at>prior_status_at or status_at=prior_status_at and incoming->>''status''=prior->>''status'')) or\n    (legacy and status_at is null and prior_status_at is null));\n  if prior->>''status'' in(''completed'',''finished'',''final'',''abandoned'') and coalesce(incoming->>''status'','''') not in(''completed'',''finished'',''final'',''abandoned'') then score_ok:=false; status_ok:=false; end if;\n  if score_ok then\n   if score_facts is distinct from prior_facts or prior->>''scoreCheckedAt'' is null and score_at is not null then\n    next_score:=(next_score-score_keys)||score_facts||jsonb_build_object(''scoreCheckedAt'',score_at);\n   end if;\n   if score_at is not null then receipt:=receipt||jsonb_build_object(''s'',score_at); end if;\n  end if;\n  if status_ok then\n   if incoming->>''status'' is distinct from prior->>''status'' or prior->>''statusCheckedAt'' is null and status_at is not null then\n    next_score:=next_score||jsonb_build_object(''status'',incoming->>''status'',''statusCheckedAt'',status_at);\n   end if;\n   if status_at is not null then receipt:=receipt||jsonb_build_object(''t'',status_at); end if;\n  end if;\n  next_score:=(next_score-controls)||jsonb_build_object(''id'',fid);\n  accepted:=array_append(accepted,next_score);\n  if receipt<>''{}''::jsonb then receipt_updates:=array_append(receipt_updates,jsonb_build_object(''id'',fid,''receipt'',receipt)); end if;\n end loop;\n -- Each incoming identity is unique. Assemble once instead of copying the growing JSON per fixture.\n select receipts||coalesce(jsonb_object_agg(item->>''id'',item->''receipt''),''{}''::jsonb) into receipts from unnest(receipt_updates) item;\n -- Bound receipts to retained fixtures. This does not delete sporting/user data.\n select coalesce(jsonb_object_agg(key,value),''{}''::jsonb) into receipts from jsonb_each(receipts) where key in(select coalesce(value->>''id'',value->>''eventId'',value->>''canonicalEventId'') from jsonb_array_elements(p_fixtures));\n if octet_length(receipts::text)>1048576 then raise exception ''Compact receipt byte budget exceeded''; end if;\n report:=coalesce(p_report,current_row.discovery_report,''{}''::jsonb)-''_fixtureObservations'';\n report:=report||jsonb_build_object(''_fixtureObservations'',receipts);\n -- Original publisher owns lease consumption, fact revision, current IDs and retention.\n if report is null or jsonb_typeof(report)<>''object'' then raise exception ''Invalid report'';end if;\n if exists(select 1 from nothingsports_fixture_read_private.integrity_pending where source_id=p_source_id and batch_xid is not null)then raise exception ''Nested canonical batch refused'';end if;\n select exists(select 1 from nothingsports_fixture_read_private.integrity_pending where source_id=p_source_id)into pending_preexisted;\n insert into nothingsports_fixture_read_private.integrity_pending(source_id,batch_xid,batch_pid)values(p_source_id,txid_current(),pg_backend_pid())on conflict(source_id)do update set batch_xid=excluded.batch_xid,batch_pid=excluded.batch_pid;\n published:=nothingsports_fixture_read_private.publish_full_complete(p_source_id,p_token,p_fixtures,p_hash,p_interval_ms);\n revision:=(published->>''revision'')::bigint;select coalesce(array_agg(value),''{}''::text[])into changed_ids from jsonb_array_elements_text(published->''changed'')v(value);\n update public.nothingsports_fixture_sources set discovery_report=report where source_id=p_source_id;\n WITH changed AS ( insert into public.nothingsports_live_scores(source_id,fixture_id,score,content_hash,first_completed_at)\n select p_source_id,s->>''id'',s,md5(s::text),case when s->>''status'' in(''completed'',''finished'',''final'') then clock_timestamp() end from unnest(accepted) s\n on conflict(source_id,fixture_id) do update set score=excluded.score,content_hash=excluded.content_hash,first_completed_at=coalesce(nothingsports_live_scores.first_completed_at,excluded.first_completed_at)\n where nothingsports_live_scores.score is distinct from excluded.score RETURNING fixture_id)SELECT coalesce(array_agg(fixture_id),''{}''::text[]) INTO score_changed_ids FROM changed;\n -- FINAL_BATCH_FLUSH: actual DML identities, no persistent ID queue.\n for sync_id in select distinct value from unnest(changed_ids||score_changed_ids)v(value) order by value loop\n  perform nothingsports_fixture_read_private.sync_fixture(p_source_id,sync_id);\n end loop;\n if not nothingsports_fixture_read_private.source_index_complete(p_source_id)then raise exception using errcode=''23514'',message=''Canonical batch final index incomplete'';end if;\n if not pending_preexisted and cardinality(changed_ids||score_changed_ids)=0 then\n  delete from nothingsports_fixture_read_private.integrity_pending where source_id=p_source_id and batch_xid=txid_current()and batch_pid=pg_backend_pid();\n else\n  update nothingsports_fixture_read_private.integrity_pending set batch_xid=null,batch_pid=null where source_id=p_source_id and batch_xid=txid_current()and batch_pid=pg_backend_pid();\n end if;\n return revision;\nend $function$\n"},{"signature":"nothingsports_fixture_read_private.publish_full_complete(text,uuid,jsonb,text,integer)","contract":{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"owner":"postgres","config":["search_path=\"\""],"strict":false,"definer":true,"parallel":"u","volatile":"v","leakproof":false,"definition":"cd48f9a1d41db6e5baac18963b6e3232"},"source":"CREATE OR REPLACE FUNCTION nothingsports_fixture_read_private.publish_full_complete(p_source_id text, p_token uuid, p_fixtures jsonb, p_hash text, p_interval_ms integer)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare current_row public.nothingsports_fixture_sources; next_revision bigint; retention_cutoff timestamptz; last_snapshot_revision bigint; changed_ids text[]:=''{}''; deleted_ids text[]:=''{}'';\nbegin\n  select * into current_row from public.nothingsports_fixture_sources where source_id=p_source_id for update;\n  if p_token is null or current_row.source_id is null or current_row.lease_token is distinct from p_token or current_row.lease_until is null or current_row.lease_until<=clock_timestamp() then raise exception ''Lease expired''; end if;\n  if p_fixtures is null or jsonb_typeof(p_fixtures)<>''array'' or p_hash is null or\n    (jsonb_array_length(p_fixtures)=0 and (p_source_id not like ''discovery-%'' or jsonb_array_length(current_row.fixtures)>0)) then raise exception ''Invalid snapshot''; end if;\n\n  -- Validate the complete caller-merged collection before any fact or history write.\n  -- Provider omissions are merged upstream; they are never deletion permission here.\n  if exists (\n    select 1 from jsonb_array_elements(p_fixtures) as payload(element)\n    where jsonb_typeof(element) is distinct from ''object''\n      or jsonb_typeof(coalesce(nullif(element->''id'',''null''::jsonb),\n           nullif(element->''eventId'',''null''::jsonb),nullif(element->''canonicalEventId'',''null''::jsonb))) is distinct from ''string''\n      or coalesce(btrim(coalesce(element->>''id'',element->>''eventId'',element->>''canonicalEventId'')),'''')=''''\n  ) then raise exception ''Invalid snapshot identity''; end if;\n  if exists (\n    select 1 from jsonb_array_elements(p_fixtures) as payload(element)\n    group by coalesce(element->>''id'',element->>''eventId'',element->>''canonicalEventId'')\n    having count(*)>1\n  ) then raise exception ''Ambiguous snapshot identity''; end if;\n\n  next_revision := current_row.revision;\n  if current_row.content_hash is not distinct from p_hash then\n    update public.nothingsports_fixture_sources\n       set checked_at=clock_timestamp(),\n           next_due_at=case when p_interval_ms=120000 then current_row.lease_until+interval ''30 seconds''\n           else clock_timestamp()+make_interval(secs=>greatest(120,least(86400,p_interval_ms/1000))) end,\n           lease_token=null,lease_until=null,failure_count=0\n     where source_id=p_source_id;\n  else\n\n  insert into public.nothingsports_fixture_snapshots(source_id,fixtures,content_hash)\n  values(p_source_id,p_fixtures,p_hash) returning revision into next_revision;\n\n  WITH changed AS (  insert into public.nothingsports_fixture_current(source_id,fixture_id,identity_keys,fixture,content_hash,updated_at)\n  select p_source_id,\n         expanded.fixture_id,\n         expanded.identity_keys,\n         expanded.fixture,\n         md5(expanded.fixture::text),\n         clock_timestamp()\n  from (\n    select fixture,\n           coalesce(fixture->>''id'',fixture->>''eventId'',fixture->>''canonicalEventId'') as fixture_id,\n           array(\n             select distinct identity_key\n             from unnest(array_remove(array[\n               fixture->>''id'', fixture->>''eventId'', fixture->>''canonicalEventId''\n             ],null) || case\n               when jsonb_typeof(fixture->''sourceEventIds'')=''array''\n               then array(select jsonb_array_elements_text(fixture->''sourceEventIds''))\n               else ''{}''::text[]\n             end) as keys(identity_key)\n             where identity_key <> ''''\n           ) as identity_keys\n    from jsonb_array_elements(p_fixtures) fixture\n  ) expanded\n  where expanded.fixture_id is not null and expanded.fixture_id <> ''''\n  on conflict(source_id,fixture_id) do update\n  set identity_keys=excluded.identity_keys,\n      fixture=excluded.fixture,\n      content_hash=excluded.content_hash,\n      updated_at=excluded.updated_at\n  where public.nothingsports_fixture_current.content_hash is distinct from excluded.content_hash RETURNING fixture_id) SELECT coalesce(array_agg(fixture_id),''{}''::text[]) INTO changed_ids FROM changed;\n\n  WITH deleted AS (  delete from public.nothingsports_fixture_current current\n   where current.source_id=p_source_id\n     and not exists (\n       select 1 from jsonb_array_elements(p_fixtures) as payload(element)\n       where coalesce(payload.element->>''id'',payload.element->>''eventId'',payload.element->>''canonicalEventId'')=current.fixture_id\n     ) RETURNING current.fixture_id) SELECT coalesce(array_agg(fixture_id),''{}''::text[]) INTO deleted_ids FROM deleted;\n\n  update public.nothingsports_fixture_sources\n     set fixtures=p_fixtures,content_hash=p_hash,revision=next_revision,\n         checked_at=clock_timestamp(),\n         next_due_at=case when p_interval_ms=120000 then current_row.lease_until+interval ''30 seconds''\n           else clock_timestamp()+make_interval(secs=>greatest(120,least(86400,p_interval_ms/1000))) end,\n         lease_token=null,lease_until=null,failure_count=0\n   where source_id=p_source_id;\n\n  end if;\n\n  retention_cutoff := clock_timestamp()-interval ''7 days'';\n  select max(revision) into last_snapshot_revision\n    from public.nothingsports_fixture_snapshots where source_id=p_source_id;\n  delete from public.nothingsports_fixture_snapshots target\n  using (\n    select revision from (\n      select revision,sum(stored_bytes) over(order by published_at,revision) as batch_bytes\n      from (\n        select revision,published_at,pg_column_size(fixtures) as stored_bytes\n        from public.nothingsports_fixture_snapshots\n        where source_id=p_source_id and revision<>next_revision\n          and revision<>last_snapshot_revision and published_at<retention_cutoff\n        order by published_at,revision limit 64\n      ) candidates\n    ) budgeted where batch_bytes<=4194304\n  ) expired\n  where target.source_id=p_source_id and target.revision=expired.revision;\n  return jsonb_build_object(''revision'',next_revision,''changed'',to_jsonb(changed_ids||deleted_ids));\nend;\n$function$\n"},{"signature":"nothingsports_fixture_read_private.selection_fields(jsonb)","contract":{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"owner":"postgres","config":["search_path=\"\""],"strict":false,"definer":false,"parallel":"u","volatile":"i","leakproof":false,"definition":"d9bad60ae66eb8157788e482a9fca783"},"source":"CREATE OR REPLACE FUNCTION nothingsports_fixture_read_private.selection_fields(v jsonb)\n RETURNS jsonb\n LANGUAGE sql\n IMMUTABLE\n SET search_path TO ''''\nAS $function$\n select jsonb_build_object(''key'',b.key,''starts'',b.\"startTimeUtc\",''home'',b.\"homeParticipantId\",''away'',b.\"awayParticipantId\",\n  ''hasKey'',v?''key'',''hasStart'',v?''startTimeUtc'',''hasHome'',v?''homeParticipantId'',''hasAway'',v?''awayParticipantId'',\n  ''participants'',to_jsonb(array(select distinct id from unnest(array[b.\"homeParticipantId\",b.\"awayParticipantId\"]||\n   nothingsports_fixture_read_private.top_match_keys(b.\"participantIds\")||nothingsports_fixture_read_private.top_match_keys(jsonb_path_query_array(b.participants,''$[*].id''))||\n   nothingsports_fixture_read_private.top_match_keys(jsonb_path_query_array(b.\"participantSlots\",''$[*].participantId''))||\n   nothingsports_fixture_read_private.top_match_keys(jsonb_path_query_array(b.\"matchupSides\",''$[*].players[*].id''))) id where id is not null order by id)))||jsonb_build_object(''calendarWindow'',nothingsports_fixture_read_private.window_fields(v))\n from jsonb_to_record(v) as b(key text,\"startTimeUtc\" text,\"homeParticipantId\" text,\"awayParticipantId\" text,\"participantIds\" jsonb,participants jsonb,\"participantSlots\" jsonb,\"matchupSides\" jsonb);\n$function$\n"},{"signature":"nothingsports_fixture_read_private.source_index_complete(text)","contract":{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"owner":"postgres","config":["search_path=\"\""],"strict":false,"definer":false,"parallel":"u","volatile":"s","leakproof":false,"definition":"85eb0ec44403c2ab6237ad76598cd2dd"},"source":"CREATE OR REPLACE FUNCTION nothingsports_fixture_read_private.source_index_complete(p_source_id text)\n RETURNS boolean\n LANGUAGE sql\n STABLE\n SET search_path TO ''''\nAS $function$\n select not exists(\n  select 1 from public.nothingsports_fixture_current c\n  left join nothingsports_fixture_read_private.fixture_context ctx using(source_id,fixture_id)\n  where c.source_id=p_source_id and (ctx.fixture_id is null or ctx.shape_version<>1))\n and not exists(\n  select 1 from (\n   select c.source_id,c.fixture_id,expected.kind,expected.token\n   from nothingsports_fixture_read_private.fixture_context c\n   cross join lateral(select 1::smallint kind,id token from unnest(c.identity_keys) id where id is not null\n    union all select 2::smallint,c.sides where c.sides is not null) expected\n   where c.source_id=p_source_id\n  ) expected full join (select * from nothingsports_fixture_read_private.fixture_tokens where source_id=p_source_id) actual\n   using(source_id,fixture_id,kind,token)\n  where expected.fixture_id is null or actual.fixture_id is null)\n and not exists(\n  select 1 from (select distinct source_id,kind,token from nothingsports_fixture_read_private.fixture_tokens where source_id=p_source_id) expected\n  full join (select * from nothingsports_fixture_read_private.source_tokens where source_id=p_source_id) actual using(source_id,kind,token)\n  where expected.source_id is null or actual.source_id is null);\n$function$\n"},{"signature":"nothingsports_fixture_read_private.sync_fixture(text,text)","contract":{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"owner":"postgres","config":["search_path=\"\""],"strict":false,"definer":false,"parallel":"u","volatile":"v","leakproof":false,"definition":"d122b4829f5505e9d394e26133c61e32"},"source":"CREATE OR REPLACE FUNCTION nothingsports_fixture_read_private.sync_fixture(p_source_id text, p_fixture_id text)\n RETURNS void\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\ndeclare raw_fixture jsonb;raw_score jsonb;identities text[];affected integer;\nbegin\n -- Canonical publishers already hold this source lock before fixture writes.\n perform 1 from public.nothingsports_fixture_sources where source_id=p_source_id for update;\n select c.fixture,c.identity_keys,s.score into raw_fixture,identities,raw_score\n from public.nothingsports_fixture_current c left join public.nothingsports_live_scores s using(source_id,fixture_id)\n where c.source_id=p_source_id and c.fixture_id=p_fixture_id;\n if not found then\n  delete from nothingsports_fixture_read_private.fixture_context where source_id=p_source_id and fixture_id=p_fixture_id;\n else\n  insert into nothingsports_fixture_read_private.fixture_context(source_id,fixture_id,identity_keys,base_key,score_key,has_score_key,participant_ids,sides,base_selection,score_selection)\n  select p_source_id,p_fixture_id,identities,f.* from nothingsports_fixture_read_private.context_fields(raw_fixture,raw_score) f\n  on conflict(source_id,fixture_id) do update set identity_keys=excluded.identity_keys,base_key=excluded.base_key,score_key=excluded.score_key,\n   has_score_key=excluded.has_score_key,participant_ids=excluded.participant_ids,sides=excluded.sides,base_selection=excluded.base_selection,score_selection=excluded.score_selection,shape_version=1\n  where row(fixture_context.identity_keys,fixture_context.base_selection,fixture_context.score_selection,fixture_context.shape_version)\n   is distinct from row(excluded.identity_keys,excluded.base_selection,excluded.score_selection,1::smallint);\n  get diagnostics affected=row_count;if affected=0 then return;end if;\n  -- Reconcile the exact set. A score-only context change must not rewrite identical tokens.\n  delete from nothingsports_fixture_read_private.fixture_tokens actual\n  where actual.source_id=p_source_id and actual.fixture_id=p_fixture_id\n    and not exists (\n      select 1 from (\n        select distinct 1::smallint kind,id token from unnest(identities) id where id is not null\n        union all select 2::smallint,sides from nothingsports_fixture_read_private.fixture_context\n          where source_id=p_source_id and fixture_id=p_fixture_id and sides is not null\n      ) expected where expected.kind=actual.kind and expected.token=actual.token\n    );\n  insert into nothingsports_fixture_read_private.fixture_tokens\n  select distinct p_source_id,p_fixture_id,1::smallint,id from unnest(identities) id where id is not null\n  union all select source_id,fixture_id,2::smallint,sides from nothingsports_fixture_read_private.fixture_context where source_id=p_source_id and fixture_id=p_fixture_id and sides is not null\n  on conflict(source_id,fixture_id,kind,token) do nothing;\n  -- Preserve the old rebuild''s repair of missing source membership too.\n  insert into nothingsports_fixture_read_private.source_tokens(source_id,kind,token)\n  select distinct desired.source_id,desired.kind,desired.token\n  from nothingsports_fixture_read_private.fixture_tokens desired\n  where desired.source_id=p_source_id and desired.fixture_id=p_fixture_id\n    and not exists(select 1 from nothingsports_fixture_read_private.source_tokens actual\n      where actual.source_id=desired.source_id and actual.kind=desired.kind and actual.token=desired.token)\n  on conflict(source_id,kind,token) do nothing;\n end if;\nend;\n$function$\n"},{"signature":"nothingsports_fixture_read_private.sync_trigger()","contract":{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"owner":"postgres","config":["search_path=\"\""],"strict":false,"definer":false,"parallel":"u","volatile":"v","leakproof":false,"definition":"6d37c27454bbb9fb7b111a98574507a8"},"source":"CREATE OR REPLACE FUNCTION nothingsports_fixture_read_private.sync_trigger()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\ndeclare cached nothingsports_fixture_read_private.fixture_context;current_selection jsonb;\nbegin\n\n if exists(select 1 from nothingsports_fixture_read_private.integrity_pending p where p.source_id=case when tg_op=''DELETE''then old.source_id else new.source_id end and p.batch_xid=txid_current()and p.batch_pid=pg_backend_pid())then\n  if tg_op=''UPDATE''and row(old.source_id,old.fixture_id)is distinct from row(new.source_id,new.fixture_id)then raise exception ''Composite identity change inside batch refused'';end if;\n  if tg_op=''DELETE''then return old;else return new;end if;\n end if;\n if tg_op=''DELETE'' then perform nothingsports_fixture_read_private.sync_fixture(old.source_id,old.fixture_id);return old;end if;\n if tg_op=''UPDATE'' and row(old.source_id,old.fixture_id) is distinct from row(new.source_id,new.fixture_id) then\n  perform nothingsports_fixture_read_private.sync_fixture(old.source_id,old.fixture_id);\n end if;\n select * into cached from nothingsports_fixture_read_private.fixture_context where source_id=new.source_id and fixture_id=new.fixture_id;\n if found and cached.shape_version=1 then\n  if tg_table_name=''nothingsports_fixture_current'' then\n   current_selection:=nothingsports_fixture_read_private.selection_fields(new.fixture);\n   if cached.identity_keys is not distinct from new.identity_keys and cached.base_selection is not distinct from current_selection then return new;end if;\n  else\n   current_selection:=nothingsports_fixture_read_private.selection_fields(new.score);\n   if cached.score_selection is not distinct from current_selection then return new;end if;\n  end if;\n end if;\n perform nothingsports_fixture_read_private.sync_fixture(new.source_id,new.fixture_id);return new;\nend;\n$function$\n"},{"signature":"nothingsports_fixture_read_private.token_membership_trigger()","contract":{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"owner":"postgres","config":["search_path=\"\""],"strict":false,"definer":false,"parallel":"u","volatile":"v","leakproof":false,"definition":"d0fe27069e4d294d7385cff736776ad6"},"source":"CREATE OR REPLACE FUNCTION nothingsports_fixture_read_private.token_membership_trigger()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\nbegin\n if tg_op=''INSERT'' then\n  perform 1 from public.nothingsports_fixture_sources where source_id=new.source_id for update;\n  insert into nothingsports_fixture_read_private.source_tokens values(new.source_id,new.kind,new.token) on conflict do nothing;return new;\n end if;\n perform 1 from public.nothingsports_fixture_sources where source_id=old.source_id for update;\n delete from nothingsports_fixture_read_private.source_tokens t where t.source_id=old.source_id and t.kind=old.kind and t.token=old.token and not exists(\n  select 1 from nothingsports_fixture_read_private.fixture_tokens f where f.source_id=t.source_id and f.kind=t.kind and f.token=t.token);\n return old;\nend;\n$function$\n"},{"signature":"nothingsports_fixture_read_private.top_match_keys(jsonb)","contract":{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"owner":"postgres","config":["search_path=\"\""],"strict":false,"definer":false,"parallel":"u","volatile":"i","leakproof":false,"definition":"0b5062260f46dfeb70e1e231db8d03db"},"source":"CREATE OR REPLACE FUNCTION nothingsports_fixture_read_private.top_match_keys(v jsonb)\n RETURNS text[]\n LANGUAGE sql\n IMMUTABLE\n SET search_path TO ''''\nAS $function$\n select array(select key from jsonb_object_keys(case when jsonb_typeof(v)=''object'' then v else ''{}''::jsonb end) key\n  union select value#>>''{}'' from jsonb_array_elements(case when jsonb_typeof(v)=''array'' then v else ''[]''::jsonb end) a(value) where jsonb_typeof(value)=''string''\n  union select v#>>''{}'' where jsonb_typeof(v)=''string'');\n$function$\n"},{"signature":"nothingsports_fixture_read_private.window_fields(jsonb)","contract":{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"owner":"postgres","config":["search_path=\"\""],"strict":false,"definer":false,"parallel":"u","volatile":"i","leakproof":false,"definition":"6a39d774a7309099a986a2e6068d33fb"},"source":"CREATE OR REPLACE FUNCTION nothingsports_fixture_read_private.window_fields(v jsonb)\n RETURNS jsonb\n LANGUAGE sql\n IMMUTABLE\n SET search_path TO ''''\nAS $function$\n select jsonb_build_object(\n  ''hasStatus'',v?''status'',''status'',v->>''status'',\n  ''hasEndDate'',v?''endDate'',''endDate'',v->>''endDate'',\n  ''hasDate'',v?''date'',''date'',v->>''date'',\n  ''hasStartDate'',v?''startDate'',''startDate'',v->>''startDate'',\n  ''hasSchedulingWindow'',v?''schedulingWindow'',''schedulingWindow'',v->''schedulingWindow'');\n$function$\n"},{"signature":"nothingsports_project_fixture_observations(jsonb,jsonb,jsonb,timestamp with time zone)","contract":{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"owner":"postgres","config":["search_path=\"\""],"strict":false,"definer":false,"parallel":"u","volatile":"s","leakproof":false,"definition":"44d1edfc00ada08fad8deb987472ad54"},"source":"CREATE OR REPLACE FUNCTION public.nothingsports_project_fixture_observations(base jsonb, score jsonb, receipt jsonb, first_complete timestamp with time zone)\n RETURNS jsonb\n LANGUAGE sql\n STABLE\n SET search_path TO ''''\nAS $function$\n select case when jsonb_typeof(base)=''object'' and (score is null or jsonb_typeof(score)=''object'')\n then base||(coalesce(score,''{}''::jsonb)||jsonb_build_object(\n  ''fixtureObservationSchema'',''fixture-observations.v1'',\n  ''scoreFactObservedAt'',coalesce(public.nothingsports_fixture_observation_time(score->>''scoreCheckedAt''),public.nothingsports_fixture_observation_time(base->>''scoreCheckedAt'')),\n  ''statusFactObservedAt'',coalesce(public.nothingsports_fixture_observation_time(score->>''statusCheckedAt''),public.nothingsports_fixture_observation_time(base->>''statusCheckedAt'')),\n  ''scoreCheckedAt'',coalesce(public.nothingsports_fixture_observation_time(receipt->>''s''),public.nothingsports_fixture_observation_time(score->>''scoreCheckedAt''),public.nothingsports_fixture_observation_time(base->>''scoreCheckedAt'')),\n  ''statusCheckedAt'',coalesce(public.nothingsports_fixture_observation_time(receipt->>''t''),public.nothingsports_fixture_observation_time(score->>''statusCheckedAt''),public.nothingsports_fixture_observation_time(base->>''statusCheckedAt'')))||\n  case when first_complete is null then ''{}''::jsonb else jsonb_build_object(''firstConfirmedCompleteAt'',first_complete) end)\n else base||coalesce(score,''{}''::jsonb)||jsonb_build_object(\n  ''fixtureObservationSchema'',''fixture-observations.v1'',\n  ''scoreFactObservedAt'',coalesce(public.nothingsports_fixture_observation_time(score->>''scoreCheckedAt''),public.nothingsports_fixture_observation_time(base->>''scoreCheckedAt'')),\n  ''statusFactObservedAt'',coalesce(public.nothingsports_fixture_observation_time(score->>''statusCheckedAt''),public.nothingsports_fixture_observation_time(base->>''statusCheckedAt'')),\n  ''scoreCheckedAt'',coalesce(public.nothingsports_fixture_observation_time(receipt->>''s''),public.nothingsports_fixture_observation_time(score->>''scoreCheckedAt''),public.nothingsports_fixture_observation_time(base->>''scoreCheckedAt'')),\n  ''statusCheckedAt'',coalesce(public.nothingsports_fixture_observation_time(receipt->>''t''),public.nothingsports_fixture_observation_time(score->>''statusCheckedAt''),public.nothingsports_fixture_observation_time(base->>''statusCheckedAt'')))||\n  case when first_complete is null then ''{}''::jsonb else jsonb_build_object(''firstConfirmedCompleteAt'',first_complete) end end;\n$function$\n"},{"signature":"nothingsports_publish_compact_scores(text,uuid,jsonb,jsonb,text,integer,jsonb)","contract":{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"owner":"postgres","config":["search_path=\"\""],"strict":false,"definer":false,"parallel":"u","volatile":"v","leakproof":false,"definition":"7e7128d57cbf89a17b592e1dfef0769e"},"source":"CREATE OR REPLACE FUNCTION public.nothingsports_publish_compact_scores(p_source_id text, p_token uuid, p_fixtures jsonb, p_scores jsonb, p_hash text, p_interval_ms integer, p_report jsonb DEFAULT NULL::jsonb)\n RETURNS bigint\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$begin return nothingsports_fixture_read_private.publish_compact_complete(p_source_id,p_token,p_fixtures,p_scores,p_hash,p_interval_ms,p_report);end$function$\n"},{"signature":"nothingsports_publish_fixture_source(text,uuid,jsonb,text,integer)","contract":{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"owner":"postgres","config":["search_path=\"\""],"strict":false,"definer":false,"parallel":"u","volatile":"v","leakproof":false,"definition":"68993b69c5054c76ad00f8c627e20651"},"source":"CREATE OR REPLACE FUNCTION public.nothingsports_publish_fixture_source(p_source_id text, p_token uuid, p_fixtures jsonb, p_hash text, p_interval_ms integer)\n RETURNS bigint\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$begin return(nothingsports_fixture_read_private.publish_full_complete(p_source_id,p_token,p_fixtures,p_hash,p_interval_ms)->>''revision'')::bigint;end$function$\n"},{"signature":"nothingsports_publish_fixture_source_report(text,uuid,jsonb,text,integer,jsonb)","contract":{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"owner":"postgres","config":["search_path=\"\""],"strict":false,"definer":false,"parallel":"u","volatile":"v","leakproof":false,"definition":"6cce2642baed98679b62e0b605396d21"},"source":"CREATE OR REPLACE FUNCTION public.nothingsports_publish_fixture_source_report(p_source_id text, p_token uuid, p_fixtures jsonb, p_hash text, p_interval_ms integer, p_report jsonb)\n RETURNS bigint\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\ndeclare next_revision bigint;\nbegin\n  if p_report is null or jsonb_typeof(p_report)<>''object'' then raise exception ''Invalid report''; end if;\n  next_revision := public.nothingsports_publish_fixture_source(p_source_id,p_token,p_fixtures,p_hash,p_interval_ms);\n  update public.nothingsports_fixture_sources set discovery_report=p_report where source_id=p_source_id;\n  return next_revision;\nend;\n$function$\n"},{"signature":"nothingsports_read_current_fixture_bundle(text[])","contract":{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"owner":"postgres","config":["search_path=\"\""],"strict":false,"definer":false,"parallel":"u","volatile":"s","leakproof":false,"definition":"ef1658b2eb58a376f368ede88730ad43"},"source":"CREATE OR REPLACE FUNCTION public.nothingsports_read_current_fixture_bundle(p_fixture_ids text[] DEFAULT NULL::text[])\n RETURNS jsonb\n LANGUAGE sql\n STABLE\n SET search_path TO ''''\nAS $function$\n with active_window as (\n  select (statement_timestamp() at time zone ''Australia/Sydney'')::date as today\n ), candidates as materialized (\n  select c.source_id,c.fixture_id,c.fixture,c.identity_keys,s.score,s.first_completed_at,\n   src.discovery_report->''_fixtureObservations''->c.fixture_id as receipt\n  from public.nothingsports_fixture_current c\n  join public.nothingsports_fixture_sources src using(source_id)\n  left join public.nothingsports_live_scores s using(source_id,fixture_id)\n  cross join active_window w\n  cross join lateral (\n   select\n    case when s.score ? ''status'' then s.score->>''status'' else c.fixture->>''status'' end as status,\n    case when s.score ? ''endDate'' then s.score->>''endDate'' else c.fixture->>''endDate'' end as end_date,\n    case when s.score ? ''date'' then s.score->>''date'' else c.fixture->>''date'' end as date,\n    case when s.score ? ''startDate'' then s.score->>''startDate'' else c.fixture->>''startDate'' end as start_date,\n    case when s.score ? ''schedulingWindow'' then s.score->''schedulingWindow'' else c.fixture->''schedulingWindow'' end as scheduling_window\n  ) f\n  cross join lateral (\n   select coalesce(nullif(f.end_date,''''),nullif(f.date,''''),nullif(f.start_date,''''),f.scheduling_window->>''endsOn'','''') as ends_on,\n    coalesce(nullif(f.date,''''),nullif(f.start_date,''''),f.scheduling_window->>''startsOn'','''') as starts_on\n  ) dates\n  where (p_fixture_ids is null or c.identity_keys && p_fixture_ids)\n   and (p_fixture_ids is not null or f.status=''live'' or (\n    (dates.ends_on !~ ''^[0-9]{4}-[0-9]{2}-[0-9]{2}$'' or dates.ends_on >= (w.today-7)::text)\n    and (dates.starts_on !~ ''^[0-9]{4}-[0-9]{2}-[0-9]{2}$'' or dates.starts_on <= (w.today+interval ''1 year'')::date::text)\n   ))\n  order by c.source_id,c.fixture_id limit 5001\n ), projected as (\n  select source_id,fixture_id,identity_keys,\n   public.nothingsports_project_fixture_observations(\n    case when p_fixture_ids is not null then fixture else\n     ((fixture-array[''editorialNarrative'',''storyline'',''fullSpiel'',''selectedSentence'',''spiel''])-\n      case when fixture->>''kind'' in(''tournament'',''major-event'',''event-card'') or fixture->>''cardKind'' in(''tournament'',''major-event'',''event-card'') then array[''subEvents''] else array[]::text[] end)||\n      case when jsonb_typeof(fixture->''storyline'')=''object'' then jsonb_build_object(''storyline'',\n       (fixture->''storyline'')-array[''hookSpoilerOff'',''hookSpoilerOn'',''synopsisSpoilerOff'',''synopsisSpoilerOn'']) else ''{}''::jsonb end\n    end,score,receipt,first_completed_at) as fixture\n  from candidates\n )\n select jsonb_build_object(''schemaVersion'',''current-fixture-bundle.v1'',''complete'',count(*)<=5000,\n  ''rows'',coalesce(jsonb_agg(to_jsonb(projected) order by source_id,fixture_id),''[]''::jsonb)) from projected;\n$function$\n"},{"signature":"nothingsports_read_current_fixture_bundle_json(text[])","contract":{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"owner":"postgres","config":["search_path=\"\""],"strict":false,"definer":false,"parallel":"u","volatile":"s","leakproof":false,"definition":"a91f9bc32b11190240bba20ff0870bd8"},"source":"CREATE OR REPLACE FUNCTION public.nothingsports_read_current_fixture_bundle_json(p_fixture_ids text[] DEFAULT NULL::text[])\n RETURNS json\n LANGUAGE sql\n STABLE\n SET search_path TO ''''\nAS $function$\n select value from public.nothingsports_read_current_fixture_bundle_json_rows(p_fixture_ids) t(value);\n$function$\n"},{"signature":"nothingsports_read_current_fixture_bundle_json_rows(text[])","contract":{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"owner":"postgres","config":["search_path=\"\""],"strict":false,"definer":false,"parallel":"u","volatile":"s","leakproof":false,"definition":"6e6a06e0ca5a3206a138cb88a400e84b"},"source":"CREATE OR REPLACE FUNCTION public.nothingsports_read_current_fixture_bundle_json_rows(p_fixture_ids text[] DEFAULT NULL::text[])\n RETURNS SETOF json\n LANGUAGE sql\n STABLE ROWS 1\n SET search_path TO ''''\nAS $function$\n select bundle from public.nothingsports_current_global_fixture_bundle where p_fixture_ids is null\n union all\n select public.nothingsports_read_current_fixture_bundle(p_fixture_ids)::json where p_fixture_ids is not null;\n$function$\n"},{"signature":"nothingsports_read_current_fixtures(text[])","contract":{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"owner":"postgres","config":["search_path=\"\""],"strict":false,"definer":false,"parallel":"u","volatile":"s","leakproof":false,"definition":"8f7e452c8a96f15ed11b50b4ea5cb751"},"source":"CREATE OR REPLACE FUNCTION public.nothingsports_read_current_fixtures(p_fixture_ids text[] DEFAULT NULL::text[])\n RETURNS TABLE(source_id text, fixture_id text, fixture jsonb, identity_keys text[])\n LANGUAGE sql\n STABLE\n SET search_path TO ''''\nAS $function$\n select c.source_id,c.fixture_id,public.nothingsports_project_fixture_observations(c.fixture,s.score,src.discovery_report->''_fixtureObservations''->c.fixture_id,s.first_completed_at),c.identity_keys\n from public.nothingsports_fixture_current c join public.nothingsports_fixture_sources src using(source_id)\n left join public.nothingsports_live_scores s using(source_id,fixture_id)\n where p_fixture_ids is null or c.identity_keys && p_fixture_ids order by c.source_id,c.fixture_id;\n$function$\n"},{"signature":"nothingsports_read_participant_fixture_bundle(text[],text[],text[],text[])","contract":{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"owner":"postgres","config":["search_path=\"\""],"strict":false,"definer":false,"parallel":"u","volatile":"s","leakproof":false,"definition":"df1f9773b0f210c122f6c55fe8425f3c"},"source":"CREATE OR REPLACE FUNCTION public.nothingsports_read_participant_fixture_bundle(p_sport_keys text[], p_known_sport_keys text[], p_participant_ids text[], p_required_ids text[] DEFAULT ''{}''::text[])\n RETURNS jsonb\n LANGUAGE sql\n STABLE\n SET search_path TO ''''\nAS $function$\nwith recursive integrity_context as materialized (\n  select source_id,fixture_id,identity_keys,sides,shape_version from nothingsports_fixture_read_private.fixture_context\n ), integrity_tokens as materialized (\n  select source_id,fixture_id,kind,token from nothingsports_fixture_read_private.fixture_tokens\n ), expected_tokens as materialized (\n  select c.source_id,c.fixture_id,w.kind,w.token from integrity_context c\n  cross join lateral(select 1::smallint kind,id token from unnest(c.identity_keys) id where id is not null\n   union all select 2::smallint,c.sides where c.sides is not null) w\n ), expected_sources as materialized (\n  select distinct source_id,kind,token from integrity_tokens\n ), inputs as (\n  select cardinality(p_sport_keys) between 1 and 256 and cardinality(p_known_sport_keys) between 1 and 256\n   and cardinality(p_participant_ids) between 1 and 1000 and cardinality(coalesce(p_required_ids,''{}''))<=5000\n   and not exists(select 1 from unnest(p_sport_keys||p_known_sport_keys||p_participant_ids||coalesce(p_required_ids,''{}'')) id where id is null or id !~ ''^[-a-zA-Z0-9_:]{1,200}$'')\n   and p_sport_keys <@ p_known_sport_keys as valid,\n   not exists(\n    select source_id,fixture_id from public.nothingsports_fixture_current\n    except select source_id,fixture_id from integrity_context where shape_version is null or shape_version=1)\n   and not exists(\n    select source_id,fixture_id,kind,token from expected_tokens\n    except select source_id,fixture_id,kind,token from integrity_tokens)\n   and not exists(\n    select t.source_id,t.fixture_id,t.kind,t.token from integrity_tokens t join integrity_context c using(source_id,fixture_id)\n    except select source_id,fixture_id,kind,token from expected_tokens)\n   and not exists(\n    select source_id,kind,token from expected_sources\n    except select source_id,kind,token from nothingsports_fixture_read_private.source_tokens)\n   and not exists(\n    select source_id,kind,token from nothingsports_fixture_read_private.source_tokens\n    except select source_id,kind,token from expected_sources) as metadata_ready,\n   (statement_timestamp() at time zone ''Australia/Sydney'')::date as today\n ), related_sources(source_id) as (\n select distinct c.source_id from nothingsports_fixture_read_private.fixture_context c cross join inputs i where i.valid and i.metadata_ready and (\n c.base_key=any(p_sport_keys) or c.score_key=any(p_sport_keys) or nullif(c.base_key,'''') is null or not c.base_key=any(p_known_sport_keys) or\n (c.has_score_key and (nullif(c.score_key,'''') is null or not c.score_key=any(p_known_sport_keys))) or\n c.identity_keys && coalesce(p_required_ids,''{}'') or c.participant_ids && p_participant_ids)\n union\n select other.source_id from related_sources r join nothingsports_fixture_read_private.source_tokens seed using(source_id)\n join nothingsports_fixture_read_private.source_tokens other on other.kind=seed.kind and other.token=seed.token\n ), protected_rows(source_id,fixture_id) as (\n select c.source_id,c.fixture_id from nothingsports_fixture_read_private.fixture_context c where c.identity_keys && coalesce(p_required_ids,''{}'')\n union\n select other.source_id,other.fixture_id from protected_rows p join nothingsports_fixture_read_private.fixture_tokens seed using(source_id,fixture_id)\n join nothingsports_fixture_read_private.fixture_tokens other on other.kind=seed.kind and other.token=seed.token\n ), calendar_inputs as materialized (\n  select c.source_id,c.fixture_id,protected.source_id is not null as protected,\n   i.today,f.status,dates.ends_on,dates.starts_on\n  from related_sources r join public.nothingsports_fixture_current c using(source_id)\n  join public.nothingsports_fixture_sources src using(source_id)\n  left join public.nothingsports_live_scores s using(source_id,fixture_id)\n  left join protected_rows protected using(source_id,fixture_id)\n  cross join inputs i\n  cross join lateral(select case when s.score ? ''status'' then s.score->>''status'' else c.fixture->>''status'' end as status,\n   case when s.score ? ''endDate'' then s.score->>''endDate'' else c.fixture->>''endDate'' end as end_date,\n   case when s.score ? ''date'' then s.score->>''date'' else c.fixture->>''date'' end as date,\n   case when s.score ? ''startDate'' then s.score->>''startDate'' else c.fixture->>''startDate'' end as start_date,\n   case when s.score ? ''schedulingWindow'' then s.score->''schedulingWindow'' else c.fixture->''schedulingWindow'' end as scheduling_window) f\n  cross join lateral(select coalesce(nullif(f.end_date,''''),nullif(f.date,''''),nullif(f.start_date,''''),f.scheduling_window->>''endsOn'','''') as ends_on,\n   coalesce(nullif(f.date,''''),nullif(f.start_date,''''),f.scheduling_window->>''startsOn'','''') as starts_on) dates\n ), candidates as materialized (\n  select c.source_id,c.fixture_id from calendar_inputs c\n  where c.protected or c.status=''live'' or (\n   (c.ends_on !~ ''^[0-9]{4}-[0-9]{2}-[0-9]{2}$'' or c.ends_on >= (c.today-7)::text) and\n   (c.starts_on !~ ''^[0-9]{4}-[0-9]{2}-[0-9]{2}$'' or c.starts_on <= (c.today+interval ''1 year'')::date::text))\n  order by c.source_id,c.fixture_id limit 5001\n ), receipts as materialized (\n  select src.source_id,r.key as fixture_id,r.value as receipt from public.nothingsports_fixture_sources src\n  join (select distinct source_id from candidates) needed using(source_id)\n  cross join lateral jsonb_each(case when jsonb_typeof(src.discovery_report->''_fixtureObservations'')=''object'' then src.discovery_report->''_fixtureObservations'' else ''{}''::jsonb end) r\n ), projected as (\n  select c.source_id,c.fixture_id,c.identity_keys,public.nothingsports_project_fixture_observations(\n   ((fixture-array[''editorialNarrative'',''storyline'',''fullSpiel'',''selectedSentence'',''spiel''])-\n    case when fixture->>''kind'' in(''tournament'',''major-event'',''event-card'') or fixture->>''cardKind'' in(''tournament'',''major-event'',''event-card'') then array[''subEvents''] else array[]::text[] end)||\n    case when jsonb_typeof(fixture->''storyline'')=''object'' then jsonb_build_object(''storyline'',\n     (fixture->''storyline'')-array[''hookSpoilerOff'',''hookSpoilerOn'',''synopsisSpoilerOff'',''synopsisSpoilerOn'']) else ''{}''::jsonb end,\n   score,r.receipt,first_completed_at) as fixture from candidates selected join public.nothingsports_fixture_current c using(source_id,fixture_id)\n   left join public.nothingsports_live_scores s using(source_id,fixture_id) left join receipts r using(source_id,fixture_id)\n )\n select jsonb_build_object(''schemaVersion'',''current-fixture-bundle.v1'',''scope'',''participants'',\n  ''sportKeys'',to_jsonb(p_sport_keys),''knownSportKeys'',to_jsonb(p_known_sport_keys),''participantIds'',to_jsonb(p_participant_ids),''requiredIds'',coalesce(to_jsonb(p_required_ids),''[]''::jsonb),\n  ''complete'',coalesce((select valid and metadata_ready from inputs),false) and count(*)<=5000,\n  ''rows'',coalesce(jsonb_agg(to_jsonb(projected) order by source_id,fixture_id),''[]''::jsonb)) from projected;\n$function$\n"}]'::jsonb)e(signature text,contract jsonb)left join pg_proc p on p.oid=to_regprocedure(e.signature)where e.contract is distinct from jsonb_build_object('definition',md5(pg_get_functiondef(p.oid)),'acl',p.proacl::text,'owner',pg_get_userbyid(p.proowner),'definer',p.prosecdef,'volatile',p.provolatile,'parallel',p.proparallel,'strict',p.proisstrict,'cost',p.procost,'leakproof',p.proleakproof,'config',p.proconfig)))then raise exception 'Exact candidate22 definition/ACL/attribute/owner/search-path contract differs; undo refused';end if;
 if exists(select 1 from nothingsports_fixture_read_private.integrity_pending where batch_xid is not null or batch_pid is not null)then raise exception 'Unclosed batch: compatible owner must rollback or finish it before undo';end if;end$undo$;
SET CONSTRAINTS ALL IMMEDIATE;
do $settled$begin if exists(select 1 from nothingsports_fixture_read_private.integrity_pending)then raise exception 'Ordinary pending warning did not drain; no forced clearing';end if;end$settled$;
CREATE OR REPLACE FUNCTION public.nothingsports_publish_fixture_source(p_source_id text, p_token uuid, p_fixtures jsonb, p_hash text, p_interval_ms integer)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare current_row public.nothingsports_fixture_sources; next_revision bigint; retention_cutoff timestamptz; last_snapshot_revision bigint;
begin
  select * into current_row from public.nothingsports_fixture_sources where source_id=p_source_id for update;
  if p_token is null or current_row.source_id is null or current_row.lease_token is distinct from p_token or current_row.lease_until is null or current_row.lease_until<=clock_timestamp() then raise exception 'Lease expired'; end if;
  if p_fixtures is null or jsonb_typeof(p_fixtures)<>'array' or p_hash is null or
    (jsonb_array_length(p_fixtures)=0 and (p_source_id not like 'discovery-%' or jsonb_array_length(current_row.fixtures)>0)) then raise exception 'Invalid snapshot'; end if;

  next_revision := current_row.revision;
  if current_row.content_hash is not distinct from p_hash then
    update public.nothingsports_fixture_sources
       set checked_at=clock_timestamp(),
           next_due_at=case when p_interval_ms=120000 then current_row.lease_until+interval '30 seconds'
           else clock_timestamp()+make_interval(secs=>greatest(120,least(86400,p_interval_ms/1000))) end,
           lease_token=null,lease_until=null,failure_count=0
     where source_id=p_source_id;
  else

  insert into public.nothingsports_fixture_snapshots(source_id,fixtures,content_hash)
  values(p_source_id,p_fixtures,p_hash) returning revision into next_revision;

  insert into public.nothingsports_fixture_current(source_id,fixture_id,identity_keys,fixture,content_hash,updated_at)
  select p_source_id,
         expanded.fixture_id,
         expanded.identity_keys,
         expanded.fixture,
         md5(expanded.fixture::text),
         clock_timestamp()
  from (
    select fixture,
           coalesce(fixture->>'id',fixture->>'eventId',fixture->>'canonicalEventId') as fixture_id,
           array(
             select distinct identity_key
             from unnest(array_remove(array[
               fixture->>'id', fixture->>'eventId', fixture->>'canonicalEventId'
             ],null) || case
               when jsonb_typeof(fixture->'sourceEventIds')='array'
               then array(select jsonb_array_elements_text(fixture->'sourceEventIds'))
               else '{}'::text[]
             end) as keys(identity_key)
             where identity_key <> ''
           ) as identity_keys
    from jsonb_array_elements(p_fixtures) fixture
  ) expanded
  where expanded.fixture_id is not null and expanded.fixture_id <> ''
  on conflict(source_id,fixture_id) do update
  set identity_keys=excluded.identity_keys,
      fixture=excluded.fixture,
      content_hash=excluded.content_hash,
      updated_at=excluded.updated_at
  where public.nothingsports_fixture_current.content_hash is distinct from excluded.content_hash;

  delete from public.nothingsports_fixture_current current
   where current.source_id=p_source_id
     and not exists (
       select 1 from jsonb_array_elements(p_fixtures) fixture
       where coalesce(fixture->>'id',fixture->>'eventId',fixture->>'canonicalEventId')=current.fixture_id
     );

  update public.nothingsports_fixture_sources
     set fixtures=p_fixtures,content_hash=p_hash,revision=next_revision,
         checked_at=clock_timestamp(),
         next_due_at=case when p_interval_ms=120000 then current_row.lease_until+interval '30 seconds'
           else clock_timestamp()+make_interval(secs=>greatest(120,least(86400,p_interval_ms/1000))) end,
         lease_token=null,lease_until=null,failure_count=0
   where source_id=p_source_id;

  end if;

  retention_cutoff := clock_timestamp()-interval '7 days';
  select max(revision) into last_snapshot_revision
    from public.nothingsports_fixture_snapshots where source_id=p_source_id;
  delete from public.nothingsports_fixture_snapshots target
  using (
    select revision from (
      select revision,sum(stored_bytes) over(order by published_at,revision) as batch_bytes
      from (
        select revision,published_at,pg_column_size(fixtures) as stored_bytes
        from public.nothingsports_fixture_snapshots
        where source_id=p_source_id and revision<>next_revision
          and revision<>last_snapshot_revision and published_at<retention_cutoff
        order by published_at,revision limit 64
      ) candidates
    ) budgeted where batch_bytes<=4194304
  ) expired
  where target.source_id=p_source_id and target.revision=expired.revision;
  return next_revision;
end;
$function$;
CREATE OR REPLACE FUNCTION public.nothingsports_publish_compact_scores(p_source_id text, p_token uuid, p_fixtures jsonb, p_scores jsonb, p_hash text, p_interval_ms integer, p_report jsonb DEFAULT NULL::jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 current_row public.nothingsports_fixture_sources; revision bigint;
 score_keys text[]:=array['homeScore','awayScore','scoreDisplay','score','sets','games','innings','rubbers','canonicalResultScoreline'];
 controls text[]:=array['observationSchema','scoreObserved','statusObserved'];
 incoming jsonb; prior jsonb; next_score jsonb; score_facts jsonb; prior_facts jsonb; base jsonb; bases jsonb; previous_scores jsonb;
 receipts jsonb; receipt jsonb; report jsonb; accepted jsonb:='[]'::jsonb;
 score_at timestamptz; status_at timestamptz; prior_score_at timestamptz; prior_status_at timestamptz;
 score_ok boolean; status_ok boolean; legacy boolean; fid text;
begin
 select * into current_row from public.nothingsports_fixture_sources where source_id=p_source_id for update;
 if p_token is null or current_row.source_id is null or current_row.lease_token is distinct from p_token or current_row.lease_until is null or current_row.lease_until<=clock_timestamp() then raise exception 'Lease expired'; end if;
 if p_scores is null or jsonb_typeof(p_scores)<>'array' or jsonb_array_length(p_scores)>5000 or
    p_fixtures is null or jsonb_typeof(p_fixtures)<>'array' or jsonb_array_length(p_fixtures)>5000 then raise exception 'Invalid compact observation budget'; end if;
 if p_report is not null and jsonb_typeof(p_report)<>'object' then raise exception 'Invalid report'; end if;
 if exists(select 1 from jsonb_array_elements(p_scores) s group by s->>'id' having count(*)>1) then raise exception 'Ambiguous compact identity'; end if;
 receipts:=coalesce(current_row.discovery_report->'_fixtureObservations','{}'::jsonb);
 select jsonb_object_agg(coalesce(value->>'id',value->>'eventId',value->>'canonicalEventId'),value) into bases from jsonb_array_elements(p_fixtures);
 select coalesce(jsonb_object_agg(fixture_id,score),'{}'::jsonb) into previous_scores from public.nothingsports_live_scores where source_id=p_source_id;
 for incoming in select value from jsonb_array_elements(p_scores) loop
  fid:=incoming->>'id';
  base:=bases->fid;
  if fid is null or fid='' or base is null then raise exception 'Unmatched compact identity'; end if;
  prior:=previous_scores->fid;
  prior:=coalesce(prior,'{}'::jsonb); next_score:=prior;
  receipt:=coalesce(receipts->fid,'{}'::jsonb);
  legacy:=incoming->>'observationSchema' is distinct from 'fixture-observations.v1';
  score_at:=public.nothingsports_fixture_observation_time(case when legacy then coalesce(incoming->>'scoreCheckedAt',base->>'scoreCheckedAt',base->>'sourceCheckedAt',base->>'canonicalSourceCheckedAt') when incoming->>'scoreObserved'='true' then incoming->>'scoreCheckedAt' end);
  status_at:=public.nothingsports_fixture_observation_time(case when legacy then coalesce(incoming->>'statusCheckedAt',base->>'statusCheckedAt',base->>'sourceCheckedAt',base->>'canonicalSourceCheckedAt') when incoming->>'statusObserved'='true' then incoming->>'statusCheckedAt' end);
  prior_score_at:=public.nothingsports_fixture_observation_time(coalesce(receipt->>'s',prior->>'scoreCheckedAt'));
  prior_status_at:=public.nothingsports_fixture_observation_time(coalesce(receipt->>'t',prior->>'statusCheckedAt'));
  select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) into score_facts from jsonb_each(incoming) where key=any(score_keys) and value<>'null'::jsonb and value<>'[]'::jsonb and value<>'{}'::jsonb and value<>'""'::jsonb;
  select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) into prior_facts from jsonb_each(prior) where key=any(score_keys) and value<>'null'::jsonb and value<>'[]'::jsonb and value<>'{}'::jsonb and value<>'""'::jsonb;
  -- Unknown-clock data can initialise legacy rows, but cannot replace known facts.
  -- Equal clocks verify the same facts; contradictory equal-clock facts are rejected.
  score_ok:=score_facts<>'{}'::jsonb and (prior='{}'::jsonb or
    (score_at is not null and (prior_score_at is null or score_at>prior_score_at or score_at=prior_score_at and score_facts=prior_facts)) or
    (legacy and score_at is null and prior_score_at is null));
  status_ok:=nullif(incoming->>'status','') is not null and (prior='{}'::jsonb or
    (status_at is not null and (prior_status_at is null or status_at>prior_status_at or status_at=prior_status_at and incoming->>'status'=prior->>'status')) or
    (legacy and status_at is null and prior_status_at is null));
  if prior->>'status' in('completed','finished','final','abandoned') and coalesce(incoming->>'status','') not in('completed','finished','final','abandoned') then score_ok:=false; status_ok:=false; end if;
  if score_ok then
   if score_facts is distinct from prior_facts or prior->>'scoreCheckedAt' is null and score_at is not null then
    next_score:=(next_score-score_keys)||score_facts||jsonb_build_object('scoreCheckedAt',score_at);
   end if;
   if score_at is not null then receipt:=receipt||jsonb_build_object('s',score_at); end if;
  end if;
  if status_ok then
   if incoming->>'status' is distinct from prior->>'status' or prior->>'statusCheckedAt' is null and status_at is not null then
    next_score:=next_score||jsonb_build_object('status',incoming->>'status','statusCheckedAt',status_at);
   end if;
   if status_at is not null then receipt:=receipt||jsonb_build_object('t',status_at); end if;
  end if;
  next_score:=(next_score-controls)||jsonb_build_object('id',fid);
  accepted:=accepted||jsonb_build_array(next_score);
  if receipt<>'{}'::jsonb then receipts:=jsonb_set(receipts,array[fid],receipt); end if;
 end loop;
 -- Bound receipts to retained fixtures. This does not delete sporting/user data.
 select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) into receipts from jsonb_each(receipts) where key in(select coalesce(value->>'id',value->>'eventId',value->>'canonicalEventId') from jsonb_array_elements(p_fixtures));
 if octet_length(receipts::text)>1048576 then raise exception 'Compact receipt byte budget exceeded'; end if;
 report:=coalesce(p_report,current_row.discovery_report,'{}'::jsonb)-'_fixtureObservations';
 report:=report||jsonb_build_object('_fixtureObservations',receipts);
 -- Original publisher owns lease consumption, fact revision, current IDs and retention.
 revision:=public.nothingsports_publish_fixture_source_report(p_source_id,p_token,p_fixtures,p_hash,p_interval_ms,report);
 insert into public.nothingsports_live_scores(source_id,fixture_id,score,content_hash,first_completed_at)
 select p_source_id,s->>'id',s,md5(s::text),case when s->>'status' in('completed','finished','final') then clock_timestamp() end from jsonb_array_elements(accepted) s
 on conflict(source_id,fixture_id) do update set score=excluded.score,content_hash=excluded.content_hash,first_completed_at=coalesce(nothingsports_live_scores.first_completed_at,excluded.first_completed_at)
 where nothingsports_live_scores.score is distinct from excluded.score;
 return revision;
end $function$;
CREATE OR REPLACE FUNCTION nothingsports_fixture_read_private.sync_fixture(p_source_id text, p_fixture_id text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare raw_fixture jsonb;raw_score jsonb;identities text[];affected integer;
begin
 -- Canonical publishers already hold this source lock before fixture writes.
 perform 1 from public.nothingsports_fixture_sources where source_id=p_source_id for update;
 select c.fixture,c.identity_keys,s.score into raw_fixture,identities,raw_score
 from public.nothingsports_fixture_current c left join public.nothingsports_live_scores s using(source_id,fixture_id)
 where c.source_id=p_source_id and c.fixture_id=p_fixture_id;
 if not found then
  delete from nothingsports_fixture_read_private.fixture_context where source_id=p_source_id and fixture_id=p_fixture_id;
 else
  insert into nothingsports_fixture_read_private.fixture_context(source_id,fixture_id,identity_keys,base_key,score_key,has_score_key,participant_ids,sides,base_selection,score_selection)
  select p_source_id,p_fixture_id,identities,f.* from nothingsports_fixture_read_private.context_fields(raw_fixture,raw_score) f
  on conflict(source_id,fixture_id) do update set identity_keys=excluded.identity_keys,base_key=excluded.base_key,score_key=excluded.score_key,
   has_score_key=excluded.has_score_key,participant_ids=excluded.participant_ids,sides=excluded.sides,base_selection=excluded.base_selection,score_selection=excluded.score_selection,shape_version=1
  where row(fixture_context.identity_keys,fixture_context.base_selection,fixture_context.score_selection,fixture_context.shape_version)
   is distinct from row(excluded.identity_keys,excluded.base_selection,excluded.score_selection,1::smallint);
  get diagnostics affected=row_count;if affected=0 then return;end if;
  delete from nothingsports_fixture_read_private.fixture_tokens where source_id=p_source_id and fixture_id=p_fixture_id;
  insert into nothingsports_fixture_read_private.fixture_tokens
  select distinct p_source_id,p_fixture_id,1::smallint,id from unnest(identities) id where id is not null
  union all select source_id,fixture_id,2::smallint,sides from nothingsports_fixture_read_private.fixture_context where source_id=p_source_id and fixture_id=p_fixture_id and sides is not null;
 end if;
end;
$function$;
CREATE OR REPLACE FUNCTION nothingsports_fixture_read_private.sync_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare cached nothingsports_fixture_read_private.fixture_context;current_selection jsonb;
begin
 if tg_op='DELETE' then perform nothingsports_fixture_read_private.sync_fixture(old.source_id,old.fixture_id);return old;end if;
 if tg_op='UPDATE' and row(old.source_id,old.fixture_id) is distinct from row(new.source_id,new.fixture_id) then
  perform nothingsports_fixture_read_private.sync_fixture(old.source_id,old.fixture_id);
 end if;
 select * into cached from nothingsports_fixture_read_private.fixture_context where source_id=new.source_id and fixture_id=new.fixture_id;
 if found and cached.shape_version=1 then
  if tg_table_name='nothingsports_fixture_current' then
   current_selection:=nothingsports_fixture_read_private.selection_fields(new.fixture);
   if cached.identity_keys is not distinct from new.identity_keys and cached.base_selection is not distinct from current_selection then return new;end if;
  else
   current_selection:=nothingsports_fixture_read_private.selection_fields(new.score);
   if cached.score_selection is not distinct from current_selection then return new;end if;
  end if;
 end if;
 perform nothingsports_fixture_read_private.sync_fixture(new.source_id,new.fixture_id);return new;
end;
$function$;
CREATE OR REPLACE FUNCTION nothingsports_fixture_read_private.enforce_pending_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if not exists(select 1 from nothingsports_fixture_read_private.integrity_pending where source_id=new.source_id) then return null;end if;
 if not nothingsports_fixture_read_private.source_index_complete(new.source_id) then
  raise exception using errcode='23514',message='Fixture index integrity is incomplete; canonical transaction refused';
 end if;
 delete from nothingsports_fixture_read_private.integrity_pending where source_id=new.source_id;
 return null;
end;
$function$;
DROP FUNCTION nothingsports_fixture_read_private.publish_full_complete(text,uuid,jsonb,text,integer),nothingsports_fixture_read_private.publish_compact_complete(text,uuid,jsonb,jsonb,text,integer,jsonb);
COMMIT;
